# ---------- utilidades ----------
def norm(x):
    if x is None:
        return ""
    s = unicodedata.normalize("NFKD", str(x))
    s = "".join(c for c in s if not unicodedata.combining(c))
    return re.sub(r"\s+", " ", s).strip().lower()

def clean(df):
    df = df.copy()
    df.columns = [str(c).strip() for c in df.columns]
    return df

def find_matrix():
    candidates = [
        ROOT / "03_MATRIZ_INTEGRACAO.xlsx",
        ROOT / "04_BASE_CONSOLIDADA.xlsx",
        ROOT / "06_MATRIZ_EVIDENCIAS.xlsx",
    ]
    for p in candidates:
        if p.exists():
            return p
    xs = list(ROOT.glob("*MATRIZ*.xlsx"))
    return xs[0] if xs else None

@st.cache_data(show_spinner=False)
def load_matrix(path):
    try:
        xl = pd.ExcelFile(path)
        frames = []
        for s in xl.sheet_names:
            try:
                df = clean(pd.read_excel(path, sheet_name=s))
                if not df.empty:
                    frames.append((s, df))
            except Exception:
                pass
        if not frames:
            return pd.DataFrame(), ""
        return max(frames, key=lambda x: len(x[1]))
    except Exception:
        return pd.DataFrame(), ""

def col(df, names):
    if df.empty:
        return None
    mp = {norm(c): c for c in df.columns}
    for n in names:
        if norm(n) in mp:
            return mp[norm(n)]
    for n in names:
        nn = norm(n)
        for k, v in mp.items():
            if nn in k or k in nn:
                return v
    return None

MATRIX_PATH = find_matrix()
if MATRIX_PATH is None:
    _loaded = (pd.DataFrame(), "")
else:
    _loaded = load_matrix(str(MATRIX_PATH))

# A matriz é uma fonte de apoio do framework. A interface visual não depende
# de uma aba específica do Excel; por isso o carregamento é feito de forma robusta.
if isinstance(_loaded, tuple) and len(_loaded) == 2:
    _a, _b = _loaded
    # Normalmente: (DataFrame, nome_da_aba)
    if isinstance(_a, pd.DataFrame):
        M, SHEET = _a, _b
    elif isinstance(_b, pd.DataFrame):
        M, SHEET = _b, _a
    else:
        M, SHEET = pd.DataFrame(), ""
elif isinstance(_loaded, pd.DataFrame):
    M, SHEET = _loaded, ""
else:
    M, SHEET = pd.DataFrame(), ""

# A ausência de dados na matriz não impede a abertura da interface.
