def axis_page(axis=None):
    """Página dos eixos com componentes nativos e cabeçalho isolado em iframe.
    O iframe evita que o HTML do hero entre na árvore React do Streamlit e elimina
    o conflito removeChild ao trocar de eixo.
    """
    page_to_axis = {
        "02 · Eixo Contábil": "Contábil",
        "03 · Eixo Financeiro": "Financeiro",
        "04 · Eixo Estratégico": "Estratégico",
    }
    axis = page_to_axis.get(st.session_state.get("page"), axis)
    if axis not in AXES:
        st.error("Eixo não identificado.")
        st.stop()

    a = AXES[axis]
    items = axis_items(axis)
    dark = a.get("dark", "#101828")
    desc = a.get("texto", "")

    # Cabeçalho dos eixos no mesmo padrão visual da página Diagnóstico.
    # O bloco é estático e isolado em iframe para não interferir na árvore React.
    hero_bg = dark
    hero_html = f"""
    <div style="
        min-height:205px;
        border-radius:0 0 30px 30px;
        padding:18px 36px 28px;
        color:#fff;
        overflow:hidden;
        position:relative;
        margin:0 0 2.5rem;
        background:{hero_bg};
        font-family:Inter,Arial,sans-serif;
        box-sizing:border-box;
    "">
      <div style="position:absolute;right:-20px;top:-75px;width:190px;height:190px;border:1px solid rgba(255,255,255,.12);border-radius:50%;"></div>
      <div style="font-size:11px;font-weight:800;letter-spacing:.16em;opacity:.72;margin-bottom:14px;position:relative;z-index:2;">{a['num']} · EIXO {axis.upper()}</div>
      <div style="font-size:56px;line-height:.95;letter-spacing:-.045em;margin:0 0 18px;font-weight:800;position:relative;z-index:2;">{axis}</div>
      <div style="font-size:14px;line-height:1.55;margin:0;max-width:850px;color:#E5E7EB;position:relative;z-index:2;">{desc}</div>
    </div>
    """
    components.html(hero_html, height=245, scrolling=False)

    st.markdown("<div class='section-kicker'>ELEMENTOS ANALISADOS</div>", unsafe_allow_html=True)
    st.markdown("## Elementos que compõem esta dimensão no framework.")

    # Chips nativos: sem HTML estrutural envolvendo widgets interativos.
    cols = st.columns(3)
    for idx, item in enumerate(items):
        with cols[idx % 3]:
            st.markdown(f"**{item}**")

    st.divider()
    st.subheader("Perguntas")
    st.markdown(
        "**Três perguntas orientam a análise de cada elemento: ele é reconhecido, mensurado e evidenciado pela empresa?**"
    )
    st.caption(
      "Marque Sim, Não ou Não identificado; perguntas ainda não preenchidas permanecem como Não respondido. "
      "O mesmo elemento pode estar relacionado a mais de um eixo."
    )

    options = ["Não respondido", "Sim", "Não", "Não identificado"]
    for item in items:
        st.markdown(f"#### {item}")
        for i, question in enumerate(a["perguntas"], 1):
            key = f"{norm(axis)}_{norm(item)}_{i}"
            current = st.session_state.scores.get(key, "Não respondido")
            if current not in options:
                current = "Não identificado"
            answer = st.selectbox(
                question,
                options,
                index=options.index(current),
                key=f"sel_{key}",
            )
            st.session_state.scores[key] = answer
        st.divider()

    pct, yes, total, answered = calc_axis(axis)
    st.subheader(f"Resultado parcial · {axis}")
    st.metric("Percentual de respostas positivas", f"{pct:.1f}%")
    if total:
        st.progress(pct / 100)
        st.caption(
            f"{yes} respostas positivas em {total} perguntas do eixo. "
            f"{answered} perguntas já respondidas."
        )
    else:
        st.caption("Nenhuma resposta válida registrada ainda.")

def render_diagnostic_percentages(results):
    """Exibe percentuais independentes e cobertura de respostas por eixo."""
    columns = st.columns(len(AXES))
    for column, axis in zip(columns, AXES):
        pct, yes, total, answered = results[axis]
        coverage = (100.0 * answered / total) if total else 0.0
        with column:
            st.markdown(f"### {axis}")
            st.metric("Respostas positivas", f"{pct:.1f}%")
            st.progress(pct / 100)
            st.caption(
                f"{yes}/{total} positivas · {answered}/{total} respondidas "
                f"({coverage:.1f}% de cobertura)"
            )

# ============================================================
# PÁGINAS DOS EIXOS — despacho da navegação
# ============================================================
if page in {"02 · Eixo Contábil", "03 · Eixo Financeiro", "04 · Eixo Estratégico"}:
    axis_page()

